def count_nums(arr):
    """
    Write a function count_nums which takes an array of integers and returns
    the number of elements which has a sum of digits > 0.
    If a number is negative, then its first signed digit will be negative:
    e.g. -123 has signed digits -1, 2, and 3.
    >>> count_nums([]) == 0
    >>> count_nums([-1, 11, -11]) == 1
    >>> count_nums([1, 1, 2]) == 3
    """
    def digit_sum_signed(n):
        # Convert to string, keeping the sign if negative
        s = str(n)
        # If negative, the first character is '-' and the first digit is negative
        if s.startswith('-'):
            first_digit_char = s[1]  # Skip the '-'
            first_digit = -int(first_digit_char)
            rest_digits = int(s[2:])
            return first_digit + digit_sum(rest_digits)
        else:
            return sum(int(d) for d in s)

    def digit_sum(n):
        if n == 0:
            return 0
        return sum(int(d) for d in str(abs(n)))

    # For each number, compute the sum of signed digits
    count = 0
    for num in arr:
        total = digit_sum_signed(num)
        if total > 0:
            count += 1
    return count
