    result = ""

    # Iterate from the second to the third-to-last character (to ensure at least one char on each side)
    for i in range(1, len(word) - 1):
        if word[i] in vowels:
            # Check if the character to the right is a consonant
            if word[i+1] not in vowels:
                # Check if the character to the left is a consonant
                if word[i-1] not in vowels:
