def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')
    left = -1

    for i, ch in enumerate(word):
        if ch in vowels and i > 0 and i < len(word) - 1:
            if word[i-1] not in vowels:
                left = i
                break
        elif ch not in vowels and ch.isalpha():
            if left == -1:
                left = i

    return word[left] if left != -1 else ""
