def is_simple_power(x, n):
    """Returns True if x is a simple power of n (i.e., there exists an integer k such that n**k = x),
    otherwise False. Also handles edge cases like non-positive x or non-integer results of the root."""
    import math

    # Handle base cases where n is 0, 1, or negative
    if n == 0:
        return False
    if n == 1:
        return False  # 1**k = 1 for any k, but we require exact match with x; if x != 1, return False.
    if n < 0:
        return False

    # If x is 0, then n^k = 0 is impossible for n > 0 and integer k >= 0
    if x == 0:
        return False

    # Calculate integer root k such that n^k = x
    # k = log_n(x) = log(x) / log(n)
    try:
        k = math.log(x) / math.log(n)
    except (ValueError, ZeroDivisionError):
        return False

    # Check if k is an integer and non-negative
    if k < 0:
        return False

    # Check if k is an integer (within floating point tolerance)
    if abs(k - round(k)) > 1e-9:
        return False

    # Verify that n**round(k) == x (to handle floating point inaccuracies)
    return n**round(k) == x
```

