def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    sequence = [n]
    while sequence[-1] != 1:
        last = sequence[-1]
        if last % 2 == 0:
            next_val = last // 2
        else:
            next_val = 3 * last + 1
        if next_val == 1:
            sequence.append(1)
        else:
            sequence.append(next_val)
        if sequence[-1] in sequence[-2:]:
            break
        if sequence[-1] > 10**18:  # safety to avoid infinite loops for very large n
            raise RecursionError("Sequence did not converge within reasonable bounds")

    odds = sorted([x for x in sequence if x % 2 == 1])
    return odds
```

