def Strongest_Extension(class_name, extensions):
    def strength(ext):
        cap = sum(1 for c in ext if c.isupper())
        sm = sum(1 for c in ext if c.islower())
        return cap - sm

    max_strength = float('-inf')
    result = extensions[0]
    for ext in extensions:
        s = strength(ext)
        if s > max_strength:
            max_strength = s
            result = ext
        elif s == max_strength:
            if ext < result:
                result = ext
    return f"{class_name}.{result}"
