def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False

    # Precompute primes up to 100 using simple trial division
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [p for p in range(2, 101) if is_prime(p)]

    # Try all combinations of 3 primes (with replacement) whose product <= a
    # Since we multiply exactly 3 primes, we can iterate through primes p1, p2, p3
    # such that p1 * p2 * p3 == a and all are prime.

    # Optimization: iterate only up to a^(1/3) for first prime, etc.
    limit = int(a ** (1/3)) + 1
    for i, p1 in enumerate(primes):
        if p1 > limit:
            break
        for j in range(i, len(primes)):
            p2 = primes[j]
            if p1 * p2 > a:
                break
            if a % (p1 * p2) == 0:
                p3 = a // (p1 * p2)
                if p3 >= p2 and is_prime(p3):
                    return True

    return False
