        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    prime_sum = 0
    if not lst:
        return 0
    max_prime = -1
    for x in lst:
        if is_prime(x):
            if x > max_prime:
                max_prime = x
                digit_sum = 0
                n = x
                while n > 0:
                    digit_sum += n % 10
                    n //= 10
                prime_sum = digit_sum
    return prime_sum if max_prime != -1 else 0
