import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """
    xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    """
    if len(xs) % 2 != 0 or len(xs) == 0:
        raise ValueError("xs must have an even number of coefficients and be non-empty.")

    def f(y):
        return poly(xs, y)

    def f_prime(y):
        if len(xs) == 2:
            return xs[1]
        # derivative coefficients: shift the list and drop the leading zero if any
        deriv_coeffs = [xs[i+1] for i in range(len(xs)-1)]
        # remove leading zero if derivative's leading coeff is zero
        while len(deriv_coeffs) > 1 and deriv_coeffs[0] == 0:
            deriv_coeffs.pop(0)
        if not deriv_coeffs:
            return 0
        # evaluate derivative at y
        return sum([coeff * math.pow(y, i) for i, coeff in enumerate(deriv_coeffs)])

    # Newton-Raphson method
    y = 1.0
    for _ in range(100):
        fy = f(y)
        if abs(fy) < 1e-15:
            break
        fp = f_prime(y)
        if abs(fp) < 1e-15:
            # fallback or break
            break
        y_new = y - fy / fp
        if abs(y_new - y) < 1e-15:
            break
        y = y_new
    return y
