def cycpattern_check(a, b):
    """You are given 2 words. You need to return True if the second word or any of its rotations is a substring in the first word"""
    def is_cyclic_rotation_substring(main, pattern):
        if not pattern:
            return True
        if len(pattern) > len(main):
            return False
        # Concatenate pattern with itself to get all its rotations
        doubled_pattern = pattern + pattern
        return pattern in main or any(pattern in main for pattern_candidate in doubled_pattern if len(pattern_candidate) == len(pattern))

    # A more direct approach: check if any rotation of b is a substring of a
    for i in range(len(b)):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True
    return False
