def newman_prime(n: int) -> int:
    """
    Return the nth Newman–Shanks–Williams (NSW) prime.

    An NSW prime is a prime p such that 2^p - 2 is divisible by p^2.
    The sequence starts: 2, 487, 1319, 1627, ...

    This implementation searches for primes p where (2**p - 2) % (p**2) == 0.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")

    count = 0
    candidate = 2

    while True:
        if is_prime(candidate):
            p_squared = candidate * candidate
            if (pow(2, candidate, p_squared) - 2) % p_squared == 0:
                count += 1
                if count == n:
                    return candidate
        candidate += 1

def is_prime(x: int) -> bool:
    if x <= 1:
        return False
    if x <= 3:
        return True
    if x % 2 == 0 or x % 3 == 0:
        return False
    i = 5
    while i * i <= x:
        if x % i == 0 or x % (i + 2) == 0:
            return False
        i += 6
    return True
