def newman_prime(n: int) -> int:
    """
    Returns the nth Newman–Shanks–Williams (NSW) prime number.
    NSW primes are prime numbers p such that p^2 + 2 is also prime.
    The sequence starts: 5, 11, 29, 499, 4001, ...

    This implementation is straightforward and suitable for reasonably small n.
    """
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num % 2 == 0:
            return False
        r = int(num**0.5)
        for i in range(3, r + 1, 2):
            if num % i == 0:
                return False
        return True

    count = 0
    candidate = 5
    while True:
        if is_prime(candidate) and is_prime(candidate * candidate + 2):
            if count == n - 1:
                return candidate
            count += 1
        candidate += 2  # NSW primes are all odd and > 2
