def sum(a: int, b: int) -> int:
    """Return the sum of all common divisors of a and b."""
    if a <= 0 or b <= 0:
        raise ValueError("Inputs must be positive integers.")

    # Compute GCD
    while b:
        a, b = b, a % b
    gcd = a

    # Sum of divisors of n = sum(d | n)
    # For n = p1^e1 * p2^e2 * ..., sum of divisors = product(sum(p_i^(k) for k in 0..e_i))

    def sum_divisors(n: int) -> int:
        factors = {}
        temp = n
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                factors[p] = count
            p += 1 if p == 2 else 2

        if temp > 1:
            factors[temp] = 1

        result = 1
        for p, e in factors.items():
            term = (p**(e+1) - 1) // (p - 1)
            result *= term
        return result

    # Sum of common divisors = sum of divisors of gcd(a, b)
    return sum_divisors(gcd)
```

