def dict_depth(d: dict) -> int:
    """
    Returns the depth of a dictionary.

    Depth rules:
      - An empty dictionary has depth 0.
      - A non-empty dictionary has depth 1 + max(depth of its values).
      - Values can be:
          * dict: depth is its own depth.
          * list/tuple: depth is 1 + max(depth of its elements).
          * scalar (int, float, str, bool, None): depth is 0.
          * nested structures (dict/list/tuple) are handled recursively.
    """
    # Base case: empty dict
    if not d:
        return 0

    def max_depth(obj):
        if isinstance(obj, dict):
            # dict: depth = 1 + max depth of its values
            if not obj:
                return 0
            return 1 + max(max_depth(v) for v in obj.values())
        elif isinstance(obj, (list, tuple)):
            # list/tuple: depth = 1 + max depth of elements
            if not obj:
                return 0
            return 1 + max(max_depth(e) for e in obj)
        else:
            # scalars
            return 0

    return max_depth(d)
```

