        return 0
    max_depth = 0
    for key, value in d.items():
        if isinstance(value, dict):
            current_depth = dict_depth(value)
            max_depth = max(max_depth, current_depth + 1)
        else:
            max_depth = max(max_depth, 1)
    return max_depth
