def pancake_sort(arr):
    n = len(arr)
    max_flip = n
    while max_flip > 1:
        idx = arr.index(max(arr[:max_flip]))
        if idx >= max_flip:
            return arr
        if idx == 0:
            max_flip -= 1
        else:
            arr[:idx+1] = arr[max_flip-1::-1][::-1]
            max_flip -= 1
    return arr
```

