def add_nested_tuples(t1, t2):
    """
    Perform element-wise addition of two nested tuples of identical structure.

    Recursively adds corresponding elements. For integers, returns sum.
    For tuples, returns a new tuple with the sum of corresponding elements.

    Raises ValueError if structures differ (different lengths or mismatched types).
    """
    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise ValueError("Both inputs must be tuples.")
    if len(t1) != len(t2):
        raise ValueError("Tuples must have the same length.")

    result = []
    for a, b in zip(t1, t2):
        if not isinstance(a, tuple) or not isinstance(b, tuple):
            result.append(a + b)
        else:
            nested_result = add_nested_tuples(a, b)
            result.append(nested_result)
    return tuple(result)
```

