def add_nested_tuples(t1, t2):
    """
    Performs index-wise addition of two nested tuples.

    Assumes:
      - Both inputs are nested tuples (e.g., (1, (2, 3)), (4, (5, 6))).
      - The structure is identical at all levels.
      - Elements at the same index are numeric (int or float).

    Returns a new nested tuple with summed elements at the same indices.
    """
    def add_elements(a, b):
        if isinstance(a, tuple) and isinstance(b, tuple):
            return tuple(add_elements(x, y) for x, y in zip(a, b))
        else:
            return float(a) + float(b)

    return add_elements(t1, t2)
