def add_nested_tuples(t1: tuple, t2: tuple) -> tuple:
    """
    Perform index-wise addition of elements between two nested tuples.
    Both tuples are assumed to have the same depth and corresponding sub-tuples
    have the same length.

    Returns a new tuple with the same structure where each element is the
    sum of the corresponding elements from the input tuples.
    """
    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise TypeError("Both inputs must be tuples.")

    def add_recursive(a, b):
        if isinstance(a, tuple):
            if not isinstance(b, tuple):
                raise ValueError("Mismatches in structure: one part is tuple, other is not.")
            if len(a) != len(b):
                raise ValueError("Mismatched tuple lengths at this level.")
            return tuple(add_recursive(x, y) for x, y in zip(a, b))
        else:
            return a + b

    result = add_recursive(t1, t2)
    return result
```

