def get_max_sum(n: int) -> int:
    """
    Computes the maximum sum value based on the recurrence:
        f(n) = max( f(n/2) + f(n/3) + f(n/4) + f(n/5),  n )
    where n/2, n/3, n/4, and n/5 are integer divisions.
    Uses memoization to avoid redundant computations.
    """
    memo = {0: 0, 1: 1}  # base cases: f(0)=0, f(1)=1

    def helper(n):
        if n in memo:
            return memo[n]
        # Recursive step
        res = n  # option 1: take n itself
        half = n // 2
        third = n // 3
        fourth = n // 4
        fifth = n // 5

        if half in memo:
            f_half = memo[half]
        else:
            f_half = helper(half)

        if third in memo:
            f_third = memo[third]
        else:
            f_third = helper(third)

        if fourth in memo:
            f_fourth = memo[fourth]
        else:
            f_fourth = helper(fourth)

        if fifth in memo:
            f_fifth = memo[fifth]
        else:
            f_fifth = helper(fifth)

        sum_recursive = f_half + f_third + f_fourth + f_fifth
        res = max(res, sum_recursive)

        memo[n] = res
        return res

    return helper(n)
```

