def list_to_float(data):
    """
    Convert all possible convertible elements in each sublist of the input list of lists to floats.

    Args:
        data (List[List[Union[int, str, float, None]]]): A list containing sublists with elements.

    Returns:
        List[List[float]]: A new list of lists where all numeric elements (int, str representing numbers, float)
                          are converted to floats. Non-numeric elements remain unchanged.
    """
    result = []
    for sublist in data:
        converted_sublist = []
        for item in sublist:
            if isinstance(item, (int, float)):
                converted_sublist.append(float(item))
            elif isinstance(item, str):
                try:
                    converted_sublist.append(float(item))
                except ValueError:
                    converted_sublist.append(item)
            else:
                converted_sublist.append(item)
        result.append(converted_sublist)

    return result
