def find_lucas(n: int) -> int:
    """Return the n'th Lucas number (L_n) where L_0 = 2, L_1 = 1, L_n = L_{n-1} + L_{n-2} for n >= 2."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1  # L_0, L_1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
```

