def find_adverb_position(sentence: str):
    """
    Returns a list of tuples (adverb, index) for the first adverbs found in the sentence.
    This implementation uses a simplified heuristic: words starting with 'a', 'e', 'i', 'o', 'u'
    followed by at least one vowel are considered adverbs.
    """
    adverbs = []
    words = sentence.lower().split()

    for word in words:
        # Skip empty strings or words that are too short to be considered adverbs
        if not word or len(word) < 2:
            continue

        vowels = set('aeiouy')
        # Check if the word starts with a vowel and has at least one vowel
        if word[0] in vowels:
            if any(c in vowels for c in word):
                adverbs.append((word, len(adverbs)))  # Store index in the list of adverbs found

    # Adjust indices to match original sentence positions
    adjusted_adverbs = []
    current_pos = 0
    for word in words:
        if word in [w[0] for w in adverbs]:
            # Find the corresponding adverb from our list
            for adv, adv_idx in adverbs:
                if adv == word:
                    # Calculate position in the original sentence
                    for idx, w in enumerate(words):
                        if w == word:
                            # Adjust the index to be the position in the sentence
                            pass
                    # For simplicity, we'll just return the list of words and their sentence positions
                    break

    # Simplified approach: return the adverbs found with their sentence positions
    adverb_positions = []
    for word in words:
        if word[0] in vowels and any(c in vowels for c in word):
            # Calculate position in the sentence (accounting for spaces)
            pos = sum(len(w) + 1 for w in words[:words.index(word)]) - len(word)
            adverb_positions.append((word, pos))

    return adverb_positions
