def first_non_repeating_character(s: str) -> str:
    """
    Returns the first character in the string `s` that does not repeat.
    If no such character exists, returns an empty string.
    """
    if not s:
        return ""

    # Count frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the first character with frequency 1
    for char in s:
        if freq[char] == 1:
            return char

    return ""
```

