def amicable_numbers_sum(limit: int) -> int:
    """
    Sum all amicable numbers in the range [1, limit].

    An amicable pair (a, b) satisfies:
        sum_divisors(a) = b and sum_divisors(b) = a, with a != b.

    This function returns the sum of all amicable numbers <= limit.
    """
    def sum_divisors(n: int) -> int:
        if n <= 1:
            return 0
        total = 1  # 1 is always a divisor for n > 1
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    amicable_sum = 0
    for n in range(1, limit + 1):
        other = sum_divisors(n)
        if other != n and other > 1:
            if sum_divisors(other) == n:
                if n <= limit:
                    amicable_sum += n
                if other <= limit:
                    amicable_sum += other
    return amicable_sum
```

