def amicable_numbers_sum(limit):
    def sum_divisors(n):
        if n == 1:
            return 1
        s = 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                s += i
                if n // i != i:
                    s += n // i
            i += 1
        if i * i == n:
            s += i
        return s

    def is_amicable(n):
        if n == 1:
            return False
        a = n
        b = sum_divisors(n)
        while True:
            if b == a:
                return False
            if b == 1:
                return False
            if b > limit:
                return False
            if n * b == a * b or b * b == a * b or b * b == a:
                return False
            c = sum_divisors(b)
            if b == c or b * c == b * n:
                return False
            if c == 1:
                return False
            a, b = b, c

    return sum(n for n in range(1, limit + 1) if is_amicable(n))
```

