def sumofFactors(n: int) -> int:
    """
    Returns the sum of all even factors of n (including 1 if n is even,
    but excluding odd factors). An even factor is a factor that is divisible by 2.
    """
    if n < 1:
        return 0

    even_factor_sum = 0

    # Iterate through all factors up to n
    for i in range(1, n + 1):
