def bitwise_xor(*tuples):
    if not tuples:
        return 0

    mask = (1 << len(tuples[0])) - 1

    for t in tuples[1:]:
        if len(t) != len(tuples[0]):
            raise ValueError("All input tuples must have the same length.")
        mask = mask | (1 << (len(tuples[0]) - len(t)))

    result = 0
    for i in range(len(tuples[0])):
        if (mask >> i) & 1:
            result |= ((tuples[0][i] >> i) & 1) << i
            for t in tuples[1:]:
                result ^= ((t[i] >> i) & 1) << i
    return result
