def bitwise_xor(*tuples):
    """
    Perform bitwise XOR across all given tuples element-wise.

    Each tuple is expected to contain integers of the same size.
    The function returns a tuple where the i-th element is the XOR
    of the i-th elements of all input tuples.

    Parameters:
        *tuples: variable number of tuple arguments containing integers.

    Returns:
        A tuple containing the result of the element-wise XOR operation.

    Raises:
        ValueError: If the input tuples do not have the same length.
    """
    if not tuples:
        return ()

    first_tuple = tuples[0]
    if not first_tuple:
        return ()

    expected_length = len(first_tuple)

    if not all(len(t) == expected_length for t in tuples):
        raise ValueError("All input tuples must have the same length.")

    result = []
    for i in range(expected_length):
        xor_val = tuples[0][i]
        for t in tuples[1:]:
            xor_val ^= t[i]
        result.append(xor_val)

    return tuple(result)
```

