def max_sub_array_sum_repeated(arr, k):
    if not arr:
        return 0

    max_subarray = max(arr)
    total_sum = sum(arr)
    min_prefix = min(arr)

    if k == 1:
        return max_subarray

    if total_sum > 0:
        if k >= 3 and min_prefix < max_subarray:
            return max_subarray + max_subarray + total_sum - min_prefix
        else:
            # For k >= 2, we can take the max subarray twice plus all elements if total_sum > 0
            return max_subarray * 2 + total_sum
    else:
        # When total_sum <= 0, we can't add the whole array, so we just take the max subarray
        return max_subarray
```

```python
def max_sub_array_sum_repeated(arr, k):
    if not arr:
        return 0

    # Case for k = 1: standard Kadane's algorithm
    max_so_far = -float('inf')
    current_max = 0
    for x in arr:
        current_max += x
        if current_max < x:
            current_max = x
        max_so_far = max(max_so_far, current_max)

    max_1 = max_so_far

    # Compute prefix and suffix maximums over the array
    prefix_max = -float('inf')
    suffix_max = -float('inf)

    prefix_sum = 0
    for x in arr:
        prefix_sum += x
        prefix_max = max(prefix_max, prefix_sum)

    suffix_sum = 0
    for x in reversed(arr):
        suffix_sum += x
        suffix_max = max(suffix_max, suffix_sum)

    # Case for k > 2: best is prefix_max + middle_sum + suffix_max
    # middle_sum is the max subarray sum in a single copy
    if k > 2:
        max_2 = prefix_max + max_1 + suffix_max
    else:
        max_2 = max_1  # for k = 2, this is not needed, but kept for uniformity

    # Final result
    if k == 1:
        return max_1
    else:
        return max(max_1, max_2)
```

