def tuple_intersection(tuple_list):
    if not tuple_list:
        return ()
    # Flatten all tuples into a single collection with indices
    flattened = []
    for i, t in enumerate(tuple_list):
        if isinstance(t, tuple):
            for x in t:
                flattened.append((x, i))

    # Create a mapping from element value to a bitmask of occurrences
    # This handles multiple identical tuples efficiently
    value_to_mask = {}
    for val, idx in flattened:
        mask = value_to_mask.get(val, 0) | (1 << idx)
        value_to_mask[val] = mask

    # Compute the intersection by finding the common elements across all tuples
    common_elements = set()
    for t in tuple_list:
        t_set = set(t)
        common_elements.intersection_update(t_set)

    # If we want to respect original tuple order, we can sort by index
    # However, the problem states "irrespective of their order", so any order is fine.
    return tuple(common_elements)
