def max_Abs_Diff(arr):
    if len(arr) < 2:
        return 0
    max_diff = 0
    for i in range(1, len(arr)):
        diff = abs(arr[i] - arr[i - 1])
        if diff > max_diff:
            max_diff = diff
    return max_diff
```

```python
def max_Abs_Diff(arr):
    if not arr or len(arr) < 2:
        return 0
    max_diff = 0
    min_val = arr[0]
    for num in arr[1:]:
        if num < min_val:
            min_val = num
        else:
            max_diff = max(max_diff, num - min_val)
    return max_diff
```

